SELECT id, customer_id, created_at
FROM orders
LIMIT 20;

SELECT customer_id, customer_name, AVG(total_amount) AS avg_total
FROM orders
GROUP BY customer_id;

SELECT id, name
FROM products
WHERE name LIKE '%' || :prefix || '%';

SELECT product_id, SUM(quantity + unit_price) AS revenue
FROM order_items
GROUP BY product_id;

SELECT id, title, status
FROM tickets
WHERE status != 'resolved';

SELECT user_id, email, MAX(logged_in_at) AS last_login
FROM logins
GROUP BY user_id;

SELECT id, name
FROM employees
WHERE manager_id = NULL;

SELECT id, sku, quantity
FROM inventory
WHERE quantity < reorder_level OR reorder_level IS NULL;

SELECT id, user_id, ends_at
FROM subscriptions
WHERE ends_at < CURRENT_DATE AND status = 'active';

SELECT customer_id, MAX(created_at) AS first_order_at
FROM orders
GROUP BY customer_id;

SELECT country
FROM customers
GROUP BY country, id;
